import{_ as e,o as i,c as t,a2 as r}from"./chunks/framework.CDpkVv68.js";const m=JSON.parse('{"title":"Variantes de hechizos y glifos","description":"","frontmatter":{},"headers":[],"relativePath":"es/guide/magic/variants-and-glyphs.md","filePath":"es/guide/magic/variants-and-glyphs.md"}'),o={name:"es/guide/magic/variants-and-glyphs.md"};function n(s,a,d,c,l,p){return i(),t("div",null,[...a[0]||(a[0]=[r('<h1 id="spell-variants-glyphs" tabindex="-1">Variantes de hechizos y glifos <a class="header-anchor" href="#spell-variants-glyphs" aria-label="Enlace permanente a &quot;Variantes de hechizos y glifos&quot;">​</a></h1><p><strong>Estado:</strong> Propuesto · Disponibilidad no confirmada.</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Enlace permanente a &quot;TL;DR&quot;">​</a></h2><ul><li>Los glifos aprendidos modifican Core Patterns (estructuras base de los hechizos) compatibles con contrapartidas.</li><li>Un presupuesto limitado de complejidad impide acumular modificadores sin límite.</li><li>Preparar un hechizo base no prepara automáticamente todas sus variantes.</li></ul><p><span id="spell-variants-and-glyphs"></span><span id="at-a-glance"></span></p><h2 id="how-it-works" tabindex="-1">Cómo funciona <a class="header-anchor" href="#how-it-works" aria-label="Enlace permanente a &quot;Cómo funciona&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Elemento</th><th>Qué significa para el jugador</th></tr></thead><tbody><tr><td>Aprender un modificador</td><td>Descubre un cambio compatible de forma, trayectoria, selección de objetivos, efecto o estabilidad.</td></tr><tr><td>Elegir una contrapartida</td><td>Obtén una ventaja táctica aceptando coste, dificultad, exposición o menor efecto en otro aspecto.</td></tr><tr><td>Preparar una variante</td><td>Puede necesitar complejidad de memoria o reconstrucción adicional; la regla sigue abierta.</td></tr></tbody></table><h2 id="compared-with-classic-uo" tabindex="-1">Comparado con UO clásico <a class="header-anchor" href="#compared-with-classic-uo" aria-label="Enlace permanente a &quot;Comparado con UO clásico&quot;">​</a></h2><table tabindex="0"><thead><tr><th>UO clásico</th><th>Orientación de Syrolands</th></tr></thead><tbody><tr><td>Magery ofrece efectos definidos, no un hechizo montado libremente para cada lanzamiento.</td><td>Se conservan patrones reconocibles, con variaciones aprendidas limitadas en lugar de construcción sin restricciones.</td></tr><tr><td>Las habilidades y recursos afectan al uso de hechizos.</td><td>Las variantes también pueden cambiar costes, dificultad, materiales y necesidades de preparación.</td></tr></tbody></table><p>Las reglas de UO varían según la época y el shard. <a href="https://uo.com/wiki/ultima-online-wiki/skills/magery/" target="_blank" rel="noreferrer">UO oficial: Magery y Meditation</a>.</p><h2 id="example" tabindex="-1">Ejemplo <a class="header-anchor" href="#example" aria-label="Enlace permanente a &quot;Ejemplo&quot;">​</a></h2><p>Un Glyph of Compression podría concentrar Fireball en un área menor. Es una alternativa táctica con una contrapartida, no una mejora garantizada ni una opción de hechizo confirmada.</p><h2 id="progression-trade-offs" tabindex="-1">Progresión y contrapartidas <a class="header-anchor" href="#progression-trade-offs" aria-label="Enlace permanente a &quot;Progresión y contrapartidas&quot;">​</a></h2><p>Inscription puede conservar variantes en libros o pergaminos. Aplicar una modificación requiere conocer el hechizo base. La compatibilidad, límites, propiedad, consumo y costes de memoria de los modificadores siguen abiertos.</p><h2 id="related" tabindex="-1">Relacionado <a class="header-anchor" href="#related" aria-label="Enlace permanente a &quot;Relacionado&quot;">​</a></h2><p><a href="/Syrolands-Public/es/guide/magic/memory-and-familiarity.html">Memoria</a> · <a href="/Syrolands-Public/es/guide/professions/inscription.html">Inscription</a> · <a href="/Syrolands-Public/es/guide/magic/learning-spells.html">Aprender hechizos</a></p><h2 id="full-design-specification" tabindex="-1">Especificación de diseño completa <a class="header-anchor" href="#full-design-specification" aria-label="Enlace permanente a &quot;Especificación de diseño completa&quot;">​</a></h2><p>Consulta la especificación de diseño: <a href="/Syrolands-Public/es/game-design/magic/variants-and-glyphs.html">Variantes de hechizos y glifos</a>.</p>',18)])])}const u=e(o,[["render",n]]);export{m as __pageData,u as default};
